styles.css:
position: relative;
overflow: hidden;
--ls-card-service-tile-border-active: var(--wp--custom--color--link--accent);

& .ls-card-service-tile__content {
	flex: 1 1 auto;
	display: flex;
	flex-direction: column;
	gap: var(--wp--preset--spacing--10);
}

& .ls-card-service-tile__index {
	position: absolute;
	top: var(--wp--preset--spacing--20);
	right: var(--wp--preset--spacing--20);
}

& .ls-card-service-tile__link::before {
	content: "";
	position: absolute;
	inset: 0;
}

& .ls-card-service-tile__link:focus-visible {
	outline: 2px solid var(--wp--custom--color--focus--ring);
	outline-offset: 2px;
}
